            badgeLabel = "अध्याय १४ • CHAPTER 14",
            title = "धर्मग्रन्थ, परम्परा र जातीय संरचना",
            subtitle = "ऐतिहासिक ग्रन्थहरूको व्याख्या, राज्यसत्ताको भूमिका र समालोचनात्मक दृष्टि",
            introduction = "जातिप्रथा कसरी जन्मियो र कसरी हजारौँ वर्षसम्म टिकिरह्यो? यो प्रश्नमा छलफल गर्दा हामीले भावनात्मक आक्रोशभन्दा माथि उठेर ऐतिहासिक, दार्शनिक र समाजशास्त्रीय सत्यतालाई सन्तुलित ढङ्गले केलाउनुपर्छ।",
            paragraphs = listOf(
                "जब जातीय विभेदको कुरा उठ्छ, प्रायः दुईवटा अतिवादी दृष्टिकोणहरू सुनिन्छन्। एकथरीले भन्छन्—'धर्म र शास्त्रको यसमा कुनै दोष नै छैन, यो त पछि मानिसहरूले बिगारेका मात्र हुन्।' अर्काथरीले भन्छन्—'सबै धार्मिक परम्परा र प्रत्येक आस्थावान् मानिस केवल जातीय शोषणका लागि मात्र बनेका हुन्।' यी दुवै अतिवादी दाबीहरूले जटिल ऐतिहासिक यथार्थलाई पूर्ण रूपमा समेट्दैनन्।",
                "पूर्वीय चिन्तन परम्परा एउटै मात्र किताब वा एउटै मात्र विचारको एकरूप संगालो होइन। एकातिर उपनिषद् र अद्वैत दर्शनका यस्ता उज्याला श्लोकहरू छन् जसले प्रत्येक जीवमा एउटै चेतना देख्छन् र 'वसुधैव कुटुम्बकम्' (संसार नै एक परिवार हो) को उद्घोष गर्छन्। बुद्ध, कबीर, रविदास र आधुनिक समाजसुधारकहरूले यही भूगोलमा उभिएर जन्मजात जातीय विभेदविरुद्ध सशक्त आवाज उठाए। तसेच, आजका लाखौँ आस्थावान् मानिसहरू मनैदेखि जातीय छुवाछुतको विरोध गर्छन्।",
